tool.command:
mkdir -p out &&
nasvar pipeline '$bam' '$repeats' '$enriched' '$sites' '$targets' '${fasta_source.fields.path}' '$gff' out/sample --config '$config' --reference '$reference' --gc_correction loess --force --log_file '$log' #if $blast_ratio: --blast_ratio $blast_ratio #end if --min_depth $advanced.min_depth --plot_y_percentile $advanced.plot_y_percentile &&
## breakpoints.fa n'est produit que si des fusions sont détectées ET le BAM est indexé. ## from_work_dir exige le fichier ; on garantit son existence (vide = pas de fusions). ## Comportement choisi pour sa prédictibilité ; alternative discover_datasets à ## évaluer ensemble si tu préfères ne pas créer de fichier vide en sortie. { test -f out/sample.breakpoints.fa || touch out/sample.breakpoints.fa; }

citations.citation:
@misc{nasvar,
  author       = {Zhao, Acacia and Wang, Jeremy},
  title        = {nasvar: Nanopore Adaptive Sample VARiant caller},
  howpublished = {\url{https://github.com/jwanglab/nasvar}},
  note         = {Version 1.1.0}
}
